import TypographyRuntime from '../../src/components/TypographyRuntime.jsx';
import React,{useState}from'react';import{createRoot}from'react-dom/client';import{BrowserRouter}from'react-router-dom';import{UIProvider}from'../../src/context/UIContext.jsx';import{api}from'../../src/api/client.js';import TamuPanel from'../../src/components/TamuPanel.jsx';import Analytics from'../../src/components/AnalitikPanel.jsx';import PenutupPanel from'../../src/components/PenutupPanel.jsx';import TypographyPanel from'../../src/components/TypographyPanel.jsx';import ViridariumTemplate from'../../src/components/templates/viridarium/ViridariumTemplate.jsx';import PublicForms from'../../src/components/PublicForms.jsx';import '../../src/styles/index.css';import '../../src/styles/atelier.css';import '../../src/components/dashboard/wedding-workspace.css';
let guests=[{id:'11111111-2222-4333-8444-555555555555',name:'Keluarga Contoh',phone:'0800000000',groupName:'Keluarga',paxLimit:2,inviteStatus:'opened',rsvp:{attending:true,guestCount:2},checkedIn:false},{id:'21111111-2222-4333-8444-555555555555',name:'Teman Contoh',groupName:'Teman',paxLimit:1,checkedIn:false},{id:'31111111-2222-4333-8444-555555555555',name:'Tamu Hadir',groupName:'Keluarga',paxLimit:2,checkedIn:true,checkInCount:1,checkedInAt:new Date().toISOString(),rsvp:{attending:true,guestCount:1}}];
api.get=async()=>({data:{guests,entitlements:{qrGuestbook:true}}});api.post=async(url,body)=>{const id=url.split('/').at(-2);guests=guests.map(g=>g.id===id?{...g,checkedIn:true,checkInCount:body.count,checkedInAt:new Date().toISOString()}:g);return{data:{message:'Berhasil dicatat.'}}};api.patch=async(_,body)=>({data:{themeSettings:body,invitation:body}});
const initial={id:'workspace-qa',slug:'qa-only',themeId:'garden-canvas',views:25,themeSettings:{characterSettings:{mode:'default',separatePose:false,cover:{scale:1,x:0,y:0},hero:{scale:1,x:0,y:0}}},invitationFeatures:{rsvpEnabled:true,wishesEnabled:true},coupleProfile:{brideName:'Aisyah',groomName:'Auf'},orders:[{status:'SUCCESS',addons:['QR_GUESTBOOK']}],wishes:[{id:'sample',senderName:'Contoh',message:'Bahagia selalu.',createdAt:new Date().toISOString()}]};
function App(){const[tab,setTab]=useState('guests'),[inv,setInv]=useState(initial),[patch,setPatch]=useState(null);const preview={...inv,...patch,themeSettings:{...inv.themeSettings,...patch?.themeSettings}};return <UIProvider><main className="atelier-app" style={{padding:28,background:'#faf8ef',minHeight:'100vh'}}><nav style={{display:'flex',gap:12,marginBottom:28}}>{[['guests','Tamu & RSVP'],['analytics','Analitik'],['closing','Penutup'],['rsvp','Konten RSVP']].map(([id,label])=><button key={id} onClick={()=>setTab(id)}>{label}</button>)}</nav>{tab==='guests'?<div className="workspace-panel"><TamuPanel fullPage autoPreview={false} invitation={inv} onUpdated={setInv}/></div>:tab==='analytics'?<Analytics invitation={inv}/>:<div style={{display:'grid',gridTemplateColumns:'minmax(330px,480px) 390px',gap:48}}><div className="panel">{tab==='closing'?<PenutupPanel invitation={inv} onUpdated={setInv} onLivePreview={setPatch}/>:<TypographyPanel mode="metrics" activeSection="rsvp" scopeOptions={['rsvp','wishes','wishList']} invitation={inv} onUpdated={setInv} onLivePreview={setPatch}/>}</div><div><button onClick={()=>{const doc=document.querySelector('iframe')?.contentDocument;doc?.querySelector('#open')?.click()}}>Buka undangan uji</button><button onClick={()=>document.querySelector('iframe')?.contentDocument.querySelector('.section-dot[data-scene="penutup"]')?.click()}>Lihat penutup uji</button><div style={{height:844,width:390,position:'relative'}}>{tab==='closing'?<ViridariumTemplate invitation={preview} editorPreview/>:<TypographyRuntime typography={preview.themeSettings.typography}><PublicForms invitation={preview} previewMode/></TypographyRuntime>}</div></div></div>}</main></UIProvider>};createRoot(document.getElementById('root')).render(<BrowserRouter><App/></BrowserRouter>);
